import React, { forwardRef } from 'react';
import { faker } from '@faker-js/faker';
import { StoryStack } from '@fiverr-private/storybook_helpers';
import type { Types } from '@fiverr-private/theme';

const contentText = faker.lorem.sentence();

export const ContentToAnimate = forwardRef<HTMLElement, Types.BoxType>((props, ref) => (
  <StoryStack ref={ref} backgroundColor="blue_700" maxWidth="400px" boxSizing="borderBox" {...props}>
    <StoryStack padding="6" color="white">
      {contentText}
    </StoryStack>
  </StoryStack>
));
ContentToAnimate.displayName = 'ContentToAnimate';
