import React from 'react';
import { Animate } from 'react-move';
import { renderChildren } from '@fiverr-private/ui_utils';
import type { SlideProps, TransitionProps } from '../../types';
import { slideTransition } from '../../utils';
import { useTransitionEvents } from '../../hooks';
import variants from './variants';

const Slide = ({
  direction = 'right',
  delay,
  duration = { enter: 'moderate3', exit: 'moderate2' },
  easing = { enter: 'easeIn', exit: 'easeOut' },
  unmountOnExit,
  in: isOpen,
  onAnimationStart,
  onAnimationEnd,
  children,
}: TransitionProps & SlideProps) => {
  const transitionStyles = slideTransition(direction);
  const computedStyle = Object.assign({ position: 'fixed' }, transitionStyles.position);
  const custom = { direction, delay, duration, easing };
  const transitionConfig = isOpen ? variants.enter(custom) : variants.exit(custom);

  const { getEventsHandler } = useTransitionEvents({
    onAnimationStart,
    onAnimationEnd,
    isOpen: !!isOpen,
    unmountOnExit,
  });

  return (
    <Animate
      show={unmountOnExit ? isOpen : true}
      start={variants.exit(custom)}
      enter={{
        ...transitionConfig,
        ...getEventsHandler('enter'),
      }}
      update={{
        ...transitionConfig,
        ...getEventsHandler('update'),
      }}
      leave={{
        ...variants.exit(custom),
        ...getEventsHandler('leave'),
      }}
    >
      {({ x, y, ...rest }) =>
        renderChildren(children, {
          style: {
            ...(children.props.style || {}),
            ...computedStyle,
            ...rest,
            transform: `translate(${x}%,${y}%)`,
          },
        })
      }
    </Animate>
  );
};

Slide.displayName = 'Slide';

export default Slide;
